{
  "r": [
    "// The repository's context files (AGENTS.md, else CLAUDE.md) in the system prompt, as pi's coding agent loads them.
import { readFile } from "node:fs/promises";
import { basename, dirname, isAbsolute, join, relative, sep } from "node:path";

import {
	defineExtension,
	type Extension,
	section,
} from "@earendil-works/pi-durable";

import { removeInvisibleCharacters } from "./security.ts";
import { git } from "./storage/git.ts";
import type { Log } from "./types.ts";
import { getErrorMessage } from "./utils.ts";

/** The built-in pi-durable extension with the `project_context` section; installed right after the coding tools. */
export const CONTEXT_EXTENSION = "pi-action-context";
export const PROJECT_CONTEXT_SECTION = "project_context";
/** In each directory, the first of these that exists is loaded. */
const CONTEXT_FILE_NAMES = ["AGENTS.md", "CLAUDE.md"] as const;
/** At most this many nested files are listed by name. */
const MAX_LISTED = 20;
const NUL = "\0";
const OBJECT_ID = /^[0-9a-f]{40}(?:[0-9a-f]{24})?$/u;

/** A context file as the model gets it. */
interface ContextFile {
	/** The absolute path, as the section shows it. */
	path: string;
	/** For the log: relative to the workspace, or `agent_dir/AGENTS.md`. */
	label: string;
	content: string;
	/** The size of the file, after removing invisible characters. */
	bytes: number;
	/** Whether `content` was cut at the size limit. */
	cut: boolean;
}

/** What `loadProjectContext` found: the section text (undefined: no section) and what went into it. */
export interface ProjectContext {
	text: string | undefined;
	files: ContextFile[];
	/** Files left out at the size limit, by label. */
	skipped: string[];
	/** Context files below `cwd`, relative to it, that the model can read when it works there. */
	nested: string[];
	/** Set when a fork pull request's files come from the base commit. */
	base: string | undefined;
}

export interface ContextFilesOptions {
	/** The agent's working directory. */
	cwd: string;
	/** `GITHUB_WORKSPACE`: the files above it are never read. When unset or not above `cwd`, `cwd` is the root. */
	workspace: string | undefined;
	/** The `agent_dir` input, resolved; the global context file is read only when it is set. */
	agentDir: string | undefined;
	/** `context_files_max_bytes`: the limit of all files together. */
	maxBytes: number;
	/** A fork pull request: read the workspace's files from its base commit instead of the checkout. */
	base?: { sha: string; remote: string } | undefined;
	log: Log;
}

/** Where the workspace's files come from: the checkout, or a commit. */
interface Source {
	/** A file's content; undefined when it doesn't exist. `rel` is relative to the root, with `/`. */
	read: (rel: string) => Promise<string | undefined>;
	/** The paths of the files named like a context file in `dir` (relative to the root) and below, relative to `dir`. */
	list: (dir: string) => Promise<string[]>;
}

/** Whether `child` is `parent` or inside it. */
function isInside(parent: string, child: string): boolean {
	const rel = relative(parent, child);
	return rel === "" || (!rel.startsWith("..") && !isAbsolute(rel));
}

const toPosix = (path: string): string => path.split(sep).join("/");

async function readOptional(path: string): Promise<string | undefined> {
	try {
		return await readFile(path, "utf8");
	} catch {
		return undefined;
	}
}

const splitNul = (out: string): string[] => out.split(NUL).filter(Boolean);

/** The files in the checkout, and the context files git knows below a directory (tracked, or untracked and not ignored). */
function checkoutSource(root: string): Source {
	return {
		read: async (rel) => readOptional(join(root, rel)),
		list: async (dir) => {
			const out = await git(join(root, dir), [
				"ls-files",
				"-z",
				"--cached",
				"--others",
				"--exclude-standard",
				"--",
				...CONTEXT_FILE_NAMES.map((name) => `:(glob)**/${name}`),
			]).catch(() => "");
			return splitNul(out);
		},
	};
}

/** The files at `sha`, fetched from `remote` when the clone doesn't have it; undefined when it can't be read. */
async function commitSource(
	root: string,
	sha: string,
	remote: string,
	log: Log,
): Promise<Source | undefined> {
	if (!OBJECT_ID.test(sha)) {
		log.warning(
			"Context files: the event names no base commit of the pull request",
		);
		return undefined;
	}
	const has = async () =>
		git(root, ["cat-file", "-e", `${sha}^{commit}`])
			.then(() => true)
			.catch(() => false);
	if (!(await has())) {
		const shallow = await git(root, ["rev-parse", "--is-shallow-repository"])
			.then((out) => out.trim() === "true")
			.catch(() => false);
		try {
			await git(root, [
				"fetch",
				"--no-tags",
				...(shallow ? ["--depth=1"] : []),
				remote,
				sha,
			]);
		} catch (error) {
			log.warning(
				`Context files: could not fetch the base commit ${sha.slice(0, 7)} of the pull request: ${getErrorMessage(error)}`,
			);
			return undefined;
		}
	}
	return {
		read: async (rel) =>
			git(root, ["show", `${sha}:./${rel}`]).catch(() => undefined),
		list: async (dir) => {
			const out = await git(join(root, dir), [
				"ls-tree",
				"-r",
				"-z",
				"--name-only",
				sha,
			]).catch(() => "");
			return splitNul(out).filter((path) =>
				(CONTEXT_FILE_NAMES as readonly string[]).includes(basename(path)),
			);
		},
	};
}

/** The first context file of `dir` (relative to the root) that `read` finds: AGENTS.md, else CLAUDE.md. */
async function firstContextFile(
	read: Source["read"],
	dir: string,
): Promise<{ rel: string; content: string } | undefined> {
	const rels = CONTEXT_FILE_NAMES.map((name) =>
		dir === "" ? name : `${dir}/${name}`,
	);
	const contents = await Promise.all(rels.map(async (rel) => read(rel)));
	const index = contents.findIndex((content) => content !== undefined);
	const rel = rels[index];
	const content = contents[index];
	return rel === undefined || content === undefined
		? undefined
		: { rel, content };
}

/** The directories from the root down to `cwd`, relative to the root (`""` is the root). */
function directoriesDown(root: string, cwd: string): string[] {
	const parts = toPosix(relative(root, cwd)).split("/").filter(Boolean);
	return ["", ...parts.map((_, index) => parts.slice(0, index + 1).join("/"))];
}

/** Of the nested files, one per directory (AGENTS.md before CLAUDE.md), without those of `cwd` itself; sorted. */
function nestedFiles(paths: readonly string[]): string[] {
	const byDir = new Map<string, string>();
	for (const path of paths) {
		const dir = dirname(path);
		const name = basename(path);
		const current = byDir.get(dir);
		if (
			dir !== "." &&
			(CONTEXT_FILE_NAMES as readonly string[]).includes(name) &&
			(current === undefined || name === CONTEXT_FILE_NAMES[0])
		) {
			byDir.set(dir, path);
		}
	}
	return [...byDir.values()].toSorted((a, b) => a.localeCompare(b));
}

/** At most `max` bytes of `text`, cut between characters. */
function cutUtf8(text: string, max: number): string {
	let bytes = 0;
	let end = 0;
	for (const char of text) {
		bytes += Buffer.byteLength(char, "utf8");
		if (bytes > max) {
			break;
		}
		end += char.length;
	}
	return text.slice(0, end);
}

/** A size for the log: `512 B`, `2.1 KiB`. */
export function formatBytes(bytes: number): string {
	return bytes < 1024 ? `${bytes} B` : `${(bytes / 1024).toFixed(1)} KiB`;
}

/** The `project_context` section text, as pi's `# Project Context` block. */
function renderProjectContext(
	context: Omit<ProjectContext, "text">,
	maxBytes: number,
): string | undefined {
	const { files, skipped, nested, base } = context;
	if (files.length === 0 && nested.length === 0) {
		return undefined;
	}
	const parts = [
		"# Project Context",
		"Project-specific instructions and guidelines:",
	];
	if (base !== undefined) {
		parts.push(
			`This pull request comes from a fork, so the repository's files below are from its base commit ${base.slice(0, 7)}, not from the pull request.`,
		);
	}
	for (const file of files) {
		parts.push(`## ${file.path}`, file.content.trim());
		if (file.cut) {
			parts.push(
				`[pi-action: this file was cut at the context_files_max_bytes limit of ${maxBytes} bytes; read it for the rest.]`,
			);
		}
	}
	if (skipped.length > 0) {
		parts.push(
			`[pi-action: not loaded, at the context_files_max_bytes limit: ${skipped.join(", ")}. Read them with your tools.]`,
		);
	}
	if (nested.length > 0) {
		const listed = nested.slice(0, MAX_LISTED).join(", ");
		const more =
			nested.length > MAX_LISTED
				? ` and ${nested.length - MAX_LISTED} more`
				: "";
		parts.push(
			`More context files: ${listed}${more}. Read the one for the directory you work in.`,
		);
	}
	return parts.join("\n\n");
}

/** The workspace's files: from the checkout, or from a fork pull request's base commit (undefined: none). */
async function openSource(
	options: ContextFilesOptions,
	root: string,
): Promise<{ source: Source | undefined; base: string | undefined }> {
	const { base, log } = options;
	if (base === undefined) {
		return { source: checkoutSource(root), base: undefined };
	}
	const source = await commitSource(root, base.sha, base.remote, log);
	if (source === undefined) {
		log.warning(
			"Context files: not loading the repository's AGENTS.md or CLAUDE.md, because this pull request comes from a fork and its base commit is not available",
		);
		return { source, base: undefined };
	}
	log.info(
		`Context files: this pull request comes from a fork, so they are read from its base commit ${base.sha.slice(0, 7)}`,
	);
	return { source, base: base.sha };
}

interface FoundFile {
	path: string;
	label: string;
	content: string;
}

/** The global context file in `agentDir`; from `source` when the directory is in the workspace. */
async function globalFile(
	agentDir: string,
	root: string,
	source: Source | undefined,
): Promise<FoundFile | undefined> {
	const inWorkspace = source !== undefined && isInside(root, agentDir);
	const file = inWorkspace
		? await firstContextFile(source.read, toPosix(relative(root, agentDir)))
		: await firstContextFile(
				async (rel) => readOptional(join(agentDir, rel)),
				"",
			);
	return file === undefined
		? undefined
		: {
				path: join(agentDir, basename(file.rel)),
				label: `agent_dir/${basename(file.rel)}`,
				content: file.content,
			};
}

/** The workspace's context files from the root down to `cwd`, in order. */
async function workspaceFiles(
	source: Source,
	root: string,
	dirs: readonly string[],
): Promise<FoundFile[]> {
	const files = await Promise.all(
		dirs.map(async (dir) => firstContextFile(source.read, dir)),
	);
	return files.flatMap((file) =>
		file === undefined
			? []
			: [
					{
						path: join(root, file.rel),
						label: file.rel,
						content: file.content,
					},
				],
	);
}

/** The files within `maxBytes` in total, without invisible characters: the one at the limit cut, later ones skipped. */
function applyLimit(
	found: readonly FoundFile[],
	maxBytes: number,
): { files: ContextFile[]; skipped: string[] } {
	const files: ContextFile[] = [];
	const skipped: string[] = [];
	let left = maxBytes;
	for (const { path, label, content: raw } of found) {
		const content = removeInvisibleCharacters(raw);
		const bytes = Buffer.byteLength(content, "utf8");
		if (left <= 0) {
			skipped.push(label);
		} else if (bytes <= left) {
			files.push({ path, label, content, bytes, cut: false });
			left -= bytes;
		} else {
			files.push({
				path,
				label,
				content: cutUtf8(content, left),
				bytes,
				cut: true,
			});
			left = 0;
		}
	}
	return { files, skipped };
}

/** The setup log: what was loaded, and a warning for what was cut or left out. */
function logContext(
	context: Omit<ProjectContext, "text">,
	maxBytes: number,
	log: Log,
): void {
	const { files, skipped, nested } = context;
	for (const file of files.filter((f) => f.cut)) {
		log.warning(
			`Context files: ${file.label} (${formatBytes(file.bytes)}) was cut at context_files_max_bytes (${maxBytes} bytes in total)`,
		);
	}
	if (skipped.length > 0) {
		log.warning(
			`Context files: not loaded, at context_files_max_bytes (${maxBytes} bytes in total): ${skipped.join(", ")}`,
		);
	}
	const loaded = files.map(
		(file) =>
			`${file.label} (${formatBytes(file.bytes)}${file.cut ? ", cut" : ""})`,
	);
	const listed = nested.length > 0 ? `; ${nested.length} more listed` : "";
	log.info(`Context files: ${loaded.join(", ") || "none"}${listed}`);
}

/**
 * The context files of a run, read once: the global one in `agent_dir` (when set), then one per directory from the
 * workspace root down to `cwd`. Never above the workspace. Files past `maxBytes` are cut or left out (a warning).
 * Invisible characters, which can hide instructions, are removed; HTML comments stay (they are common in AGENTS.md).
 */
export async function loadProjectContext(
	options: ContextFilesOptions,
): Promise<ProjectContext> {
	const { cwd, agentDir, maxBytes, log } = options;
	const root =
		options.workspace !== undefined && isInside(options.workspace, cwd)
			? options.workspace
			: cwd;
	const { source, base } = await openSource(options, root);
	const dirs = directoriesDown(root, cwd);
	const [global, local, nested] = await Promise.all([
		agentDir === undefined ? undefined : globalFile(agentDir, root, source),
		source === undefined ? [] : workspaceFiles(source, root, dirs),
		source === undefined ? [] : source.list(dirs.at(-1) ?? ""),
	]);
	const { files, skipped } = applyLimit(
		// agent_dir may be one of the directories, such as the root: its file comes once, first.
		[
			...(global === undefined ? [] : [global]),
			...local.filter((file) => file.path !== global?.path),
		],
		maxBytes,
	);
	const context = { files, skipped, nested: nestedFiles(nested), base };
	logContext(context, maxBytes, log);
	return { ...context, text: renderProjectContext(context, maxBytes) };
}

/**
 * The `pi-action-context` extension: the `project_context` section with `text`, read once for the run, so that the
 * agent's edits of AGENTS.md during the run don't change the prompt (and its cache). No section when `text` is
 * undefined.
 */
export function contextExtension(text: string | undefined): Extension {
	return defineExtension({
		name: CONTEXT_EXTENSION,
		sections: [section(PROJECT_CONTEXT_SECTION, () => text)],
	});
}
",
    "// Agent Skills (https://agentskills.io), as in pi: directories with a SKILL.md, listed in the system prompt so the model
// reads one when a task matches it, and `/skill:<name>` to put a skill's instructions in the request.
import {
	existsSync,
	readdirSync,
	readFileSync,
	realpathSync,
	statSync,
} from "node:fs";
import { basename, dirname, join } from "node:path";

import { type PromptSection, section } from "@earendil-works/pi-durable";

import type { Trigger } from "./triggers.ts";
import type { Log } from "./types.ts";

/** Where skills come from: SKILL.md files, or directories searched for them. */
export interface SkillSource {
	/** Shown in the log: a package name, `project`, or `agent_dir`. */
	source: string;
	paths: readonly string[];
}

export interface Skill {
	name: string;
	description: string;
	/** The absolute path of its SKILL.md. */
	filePath: string;
	/** The skill's directory, which its relative paths are relative to. */
	baseDir: string;
	source: string;
	/** `disable-model-invocation: true`: not listed for the model, only `/skill:<name>`. */
	disableModelInvocation: boolean;
}

/** The skills by name: the first source with a name wins. */
export type Skills = ReadonlyMap<string, Skill>;

const SKILL_FILE = "SKILL.md";
const MAX_NAME_LENGTH = 64;
const MAX_DESCRIPTION_LENGTH = 1024;
const NAME = /^[a-z0-9]+(?:-[a-z0-9]+)*$/u;
const FRONTMATTER = /^---\r?\n(?<yaml>[\s\S]*?)\r?\n?---[ \t]*(?:\r?\n|$)/u;
const KEY = /^(?<key>[A-Za-z0-9_-]+):(?:[ \t]+(?<value>.*?))?[ \t]*$/u;
const BLOCK = /^[|>][+-]?$/u;
const INDENTED = /^[ \t]/u;
const INDENT = /^[ \t]*/u;
const LINE_BREAK = /\r?\n/u;
const COMMENT = /\s+#.*$/u;
const SKILL_COMMAND = /^\/skill:(?<name>\S*)(?:\s+(?<rest>[\s\S]*))?$/u;
const XML_SPECIAL = /[&<>"']/gu;
const XML_ENTITIES: Record<string, string> = {
	"&": "&amp;",
	"<": "&lt;",
	">": "&gt;",
	'"': "&quot;",
	"'": "&apos;",
};

/** A YAML scalar as written in one line: quotes removed, `'` and `"` escapes resolved, a trailing comment cut. */
function scalar(raw: string): string {
	if (raw.startsWith('"') && raw.endsWith('"') && raw.length > 1) {
		try {
			return String(JSON.parse(raw));
		} catch {
			return raw.slice(1, -1);
		}
	}
	if (raw.startsWith("'") && raw.endsWith("'") && raw.length > 1) {
		return raw.slice(1, -1).replaceAll("''", "'");
	}
	return raw.replace(COMMENT, "");
}

/** A block scalar's lines (`|` keeps line breaks, `>` folds them), without their common indentation. */
function blockScalar(style: string, lines: readonly string[]): string {
	const indents = lines
		.filter((line) => line.trim() !== "")
		.map((line) => INDENT.exec(line)?.[0].length ?? 0);
	const indent = Math.min(...indents);
	const text = lines.map((line) => line.slice(indent));
	if (style.startsWith("|")) {
		return text.join("\n").trim();
	}
	return text
		.join("\n")
		.split(/\n[ \t]*\n/u)
		.map((paragraph) => paragraph.replaceAll("\n", " ").trim())
		.join("\n")
		.trim();
}

/**
 * The top-level fields of a file's YAML frontmatter, as strings: `key: value`, quoted values, values that go on in
 * indented lines, and block scalars (`|`, `>`). Nested maps (`metadata:`) are left out. Undefined without frontmatter.
 */
export function parseFrontmatter(
	text: string,
): Map<string, string> | undefined {
	const yaml = FRONTMATTER.exec(text)?.groups?.["yaml"];
	if (yaml === undefined) {
		return undefined;
	}
	const fields = new Map<string, string>();
	const lines = yaml.split(LINE_BREAK);
	for (let index = 0; index < lines.length; index += 1) {
		const match = KEY.exec(lines[index] ?? "");
		if (match?.groups !== undefined) {
			const key = match.groups["key"] ?? "";
			const value = match.groups["value"] ?? "";
			const rest: string[] = [];
			while (index + 1 < lines.length) {
				const next = lines[index + 1] ?? "";
				if (!(INDENTED.test(next) || next.trim() === "")) {
					break;
				}
				rest.push(next);
				index += 1;
			}
			if (BLOCK.test(value)) {
				fields.set(key, blockScalar(value, rest));
			} else if (value !== "") {
				const more = rest.map((line) => line.trim()).filter(Boolean);
				fields.set(key, scalar([value, ...more].join(" ")));
			}
		}
	}
	return fields;
}

/** Whether a frontmatter flag is true (`true`, `yes`, `on`, in any case). */
function isTrue(value: string | undefined): boolean {
	return ["true", "yes", "on"].includes((value ?? "").trim().toLowerCase());
}

function isDirectory(path: string): boolean {
	return existsSync(path) && statSync(path).isDirectory();
}

/**
 * The SKILL.md files at `path`: the file itself, or, in a directory, its SKILL.md, else the ones in its
 * subdirectories, recursively. A skill's own subdirectories are its resources, not skills. Hidden directories and
 * node_modules are skipped.
 */
function skillFiles(path: string, seen = new Set<string>()): string[] {
	if (!existsSync(path)) {
		return [];
	}
	if (!isDirectory(path)) {
		return basename(path) === SKILL_FILE ? [path] : [];
	}
	const real = realpathSync(path);
	if (seen.has(real)) {
		return [];
	}
	seen.add(real);
	const own = join(path, SKILL_FILE);
	if (existsSync(own) && !isDirectory(own)) {
		return [own];
	}
	return readdirSync(path)
		.filter((name) => !name.startsWith(".") && name !== "node_modules")
		.toSorted()
		.flatMap((name) => {
			const full = join(path, name);
			return isDirectory(full) ? skillFiles(full, seen) : [];
		});
}

/** Why a skill's frontmatter breaks the Agent Skills rules; undefined when it doesn't. */
function invalidReason(
	fields: ReadonlyMap<string, string> | undefined,
	dir: string,
): string | undefined {
	if (fields === undefined) {
		return "it has no frontmatter";
	}
	const name = fields.get("name") ?? "";
	const description = fields.get("description") ?? "";
	if (name === "") {
		return "it has no name";
	}
	if (name.length > MAX_NAME_LENGTH || !NAME.test(name)) {
		return `its name "${name}" must be at most ${MAX_NAME_LENGTH} characters of a-z, 0-9, and single hyphens inside`;
	}
	if (name !== basename(dir)) {
		return `its name "${name}" is not the name of its directory, ${basename(dir)}`;
	}
	if (description.trim() === "") {
		return "it has no description";
	}
	if (description.length > MAX_DESCRIPTION_LENGTH) {
		return `its description is longer than ${MAX_DESCRIPTION_LENGTH} characters`;
	}
	return undefined;
}

/**
 * Loads the skills of every source, in order. A skill whose frontmatter breaks the Agent Skills rules is skipped,
 * and when names collide, the first one wins; the log says which ones it skips.
 */
export function loadSkills(
	sources: readonly SkillSource[],
	log: Log,
): Map<string, Skill> {
	const skills = new Map<string, Skill>();
	for (const { source, paths } of sources) {
		for (const filePath of paths.flatMap((path) => skillFiles(path))) {
			const baseDir = dirname(filePath);
			const fields = parseFrontmatter(readFileSync(filePath, "utf8"));
			const reason = invalidReason(fields, baseDir);
			const name = fields?.get("name") ?? "";
			const taken = skills.get(name);
			if (reason !== undefined) {
				log.warning(`Skill ${filePath} from ${source} is skipped: ${reason}`);
			} else if (taken === undefined) {
				skills.set(name, {
					name,
					description: (fields?.get("description") ?? "").trim(),
					filePath,
					baseDir,
					source,
					disableModelInvocation: isTrue(
						fields?.get("disable-model-invocation"),
					),
				});
			} else {
				log.warning(
					`Skill ${name} from ${source} is ignored: ${taken.source} has one with that name`,
				);
			}
		}
	}
	return skills;
}

const escapeXml = (text: string): string =>
	text.replaceAll(XML_SPECIAL, (char) => XML_ENTITIES[char] ?? char);

/**
 * The text of the `available_skills` section: the skills the model may use, with how to read them (`read` names
 * the tool or function that reads a file). Undefined when there are none.
 */
export function formatSkillsSection(
	skills: Skills,
	read: string,
): string | undefined {
	const listed = [...skills.values()].filter(
		(skill) => !skill.disableModelInvocation,
	);
	if (listed.length === 0) {
		return undefined;
	}
	return [
		"The following skills provide specialized instructions for specific tasks.",
